import { LngLat, MercatorCoordinate } from 'maplibre-gl';
export const lngLatToMercator = (lngLat) => {
    return MercatorCoordinate.fromLngLat(lngLat, 0);
};
export const mercatorToCartesian = (mercator, scale = mercator.meterInMercatorCoordinateUnits()) => {
    return { x: mercator.x / scale, y: mercator.y / scale };
};
export const lngLatToCartesian = (lngLat, scale) => {
    const mercator = lngLatToMercator(lngLat);
    return mercatorToCartesian(mercator, scale);
};
export const cartesianToMercator = (x, y, scale) => {
    return new MercatorCoordinate(x * scale, y * scale, 0);
};
export const cartesianToLngLat = (x, y, scale) => {
    const mercator = cartesianToMercator(x, y, scale);
    return mercator.toLngLat();
};
