<script lang="ts">
	import { SensorClient } from '@viamrobotics/sdk'
	import { createResourceClient, createResourceQuery } from '@viamrobotics/svelte-sdk'

	import ApiSection from '../../api-section.svelte'
	import ConnectionStatus from '../../connection-status.svelte'
	import Query from '../../query.svelte'
	import ReadingsList from '../../readings-list.svelte'
	import RefetchController from '../../refetch-controller.svelte'
	import { createRefetchIntervalStore } from '../../refetch-interval-store.svelte'

	interface Props {
		partID: string
		resourceName: string
	}

	const { partID, resourceName }: Props = $props()

	const refetchInterval = createRefetchIntervalStore(
		() => partID,
		() => resourceName,
		'sensor'
	)

	const client = createResourceClient(
		SensorClient,
		() => partID,
		() => resourceName
	)

	const readingsQuery = createResourceQuery(client, 'getReadings', () => ({
		refetchInterval: refetchInterval.current,
	}))
</script>

<ConnectionStatus {partID}>
	{#snippet connected()}
		<div class="p-4 pb-3">
			<RefetchController
				{refetchInterval}
				queries={[readingsQuery]}
			/>
		</div>

		<ApiSection
			title="GetReadings"
			api="rdk:component:sensor"
			class="relative"
		>
			<Query
				query={readingsQuery}
				contentCx="h-6"
			>
				{#if readingsQuery.data !== undefined}
					<ReadingsList data={readingsQuery.data} />
				{/if}
			</Query>
		</ApiSection>
	{/snippet}
</ConnectionStatus>
