import { getContext, setContext } from 'svelte';
import { SvelteSet } from 'svelte/reactivity';
import { MathUtils } from 'three';
import { labelToColor } from "./color.js";
/**
 * Adds ids to detections.
 */
export const addIdsToDetections = (detections) => {
    return detections.map((detection) => ({
        ...detection,
        id: MathUtils.generateUUID(),
        confidence: Math.round(detection.confidence * 100),
        color: labelToColor(detection.className),
    }));
};
export const DETECTIONS_CONTEXT_KEY = Symbol('detections-context');
const categorize = (list) => {
    const labels = {};
    for (const detection of list) {
        labels[detection.className] ??= {
            color: labelToColor(detection.className),
            detections: [],
        };
        labels[detection.className]?.detections.push(detection);
    }
    return labels;
};
export const createDetectionContext = (getDetections) => {
    const detections = $derived(addIdsToDetections(getDetections()));
    const detectionsByLabel = $derived(categorize(detections));
    const hovered = new SvelteSet();
    let selected = $state(null);
    const context = {
        get current() {
            return detections;
        },
        get byLabel() {
            return detectionsByLabel;
        },
        hovered,
        get selected() {
            return selected;
        },
        set selected(value) {
            selected = value;
        },
    };
    return context;
};
export const provideDetectionsContext = (next) => {
    const context = createDetectionContext(next);
    setContext(DETECTIONS_CONTEXT_KEY, context);
    return context;
};
export const useDetections = () => {
    return getContext(DETECTIONS_CONTEXT_KEY);
};
