import { createMutation, useQueryClient, } from '@tanstack/svelte-query';
import { createQueryLogger } from '../logger';
export const createResourceMutation = (client, method, queryKey) => {
    const queryClient = useQueryClient();
    const name = $derived(client.name);
    const partID = $derived(client.partID);
    const methodName = $derived(String(method));
    const key = $derived(queryKey?.());
    const mutationOptions = $derived({
        mutationKey: [
            'viam-svelte-sdk',
            'partID',
            partID,
            'resource',
            name,
            methodName,
        ],
        mutationFn: async (request) => {
            const clientFunc = client.current?.[method];
            if (typeof clientFunc !== 'function') {
                throw new TypeError(`${String(method)} is not a method on the resource client.`);
            }
            const logger = createQueryLogger(name ?? 'unknown', methodName);
            logger.request(request);
            try {
                const response = (await clientFunc.apply(client.current, request));
                logger.response(response);
                return response;
            }
            catch (error) {
                logger.error(error);
                throw error;
            }
        },
        onMutate: async (request) => {
            if (!key) {
                return;
            }
            await queryClient.cancelQueries({ queryKey: key });
            const previousData = await queryClient.getQueryData(key);
            queryClient.setQueryData(key, request[0]);
            return { previousData };
        },
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        onError: (_error, _request, context) => {
            if (context?.previousData && key) {
                queryClient.setQueryData(key, context.previousData);
            }
        },
        onSettled: () => {
            if (!key) {
                return;
            }
            queryClient.invalidateQueries({ queryKey: key });
        },
    });
    return createMutation(() => mutationOptions);
};
