<script lang="ts">
	import AngleUnitToggle from '../../angle-unit-toggle.svelte'
	import CopyButton from '../../copy-button.svelte'
	import Table from '../../table.svelte'
	import { degreesToRadians, formatNumeric } from '../../../format'

	interface Props {
		positions: number[]
	}

	const { positions }: Props = $props()

	let useRadians = $state(false)

	const displayPositions = $derived(
		positions.map((pos) => (useRadians ? degreesToRadians(pos) : pos))
	)

	const copyData = $derived(`[${displayPositions.join(', ')}]`)
</script>

<div class="flex min-w-0 flex-col gap-4">
	<!-- Controls Header -->
	<div class="flex items-center justify-between">
		<span class="text-sm">Current Positions</span>
		<div class="flex gap-1">
			<AngleUnitToggle
				{useRadians}
				onToggle={() => {
					useRadians = !useRadians
				}}
			/>
			<CopyButton data={copyData} />
		</div>
	</div>

	<Table>
		<thead>
			<tr>
				<th> Joint </th>
				<th>Position ({useRadians ? 'radians' : 'degrees'})</th>
			</tr>
		</thead>
		<tbody>
			<!-- joint ids are just the index in the list of values, we need to use index for the key -->
			{#each displayPositions as pos, index (index)}
				<tr>
					<th> {index} </th>
					<th> {formatNumeric(pos)} </th>
				</tr>
			{/each}
		</tbody>
	</Table>
</div>
