export const DEFAULT_JOG_QUEUE_TIMING = {
    sendDebounceMs: 300,
    holdRepeatDelayMs: 400,
    holdRepeatIntervalMs: 150,
    resultDisplayMs: 1200,
};
/** The position the entry moves its joint to, in degrees. */
export const jogTargetDegrees = (entry) => entry.startDegrees + entry.deltaDegrees;
// A step that would cross a joint limit is cut at the limit, so 350° jogged by 15° toward a 360° limit moves the remaining 10°.
const clampDelta = (range, deltaDegrees) => Math.min(Math.max(range.startDegrees + deltaDegrees, range.minDegrees), range.maxDegrees) -
    range.startDegrees;
/**
 * Collects jog presses into one move per joint. Presses within the debounce
 * window, and repeats while a button is held, add to that joint's entry. The
 * total is sent once the joint's input goes quiet. Each joint has its own
 * entry and timers, so jogging a second joint leaves the first joint's badge
 * to run through sending, its result, and clearing on its own.
 */
export const useJogQueue = ({ send, timing = DEFAULT_JOG_QUEUE_TIMING }) => {
    // $state.raw: the map is replaced wholesale on every change so readers re-run without deep proxies.
    let entries = $state.raw(new Map());
    const debounceTimers = new Map();
    const resultTimers = new Map();
    let holdDelayTimer;
    let holdRepeatTimer;
    let heldJointIndex;
    const setEntry = (jointIndex, entry) => {
        const next = new Map(entries);
        if (entry) {
            next.set(jointIndex, entry);
        }
        else {
            next.delete(jointIndex);
        }
        entries = next;
    };
    const clearHoldTimers = () => {
        clearTimeout(holdDelayTimer);
        clearInterval(holdRepeatTimer);
    };
    const committedTargets = () => {
        const targets = new Map();
        for (const entry of entries.values()) {
            if (entry.status === 'sending' || entry.status === 'sent') {
                targets.set(entry.jointIndex, jogTargetDegrees(entry));
            }
        }
        return targets;
    };
    const flush = async (jointIndex) => {
        clearTimeout(debounceTimers.get(jointIndex));
        const entry = entries.get(jointIndex);
        if (entry?.status !== 'queuing')
            return;
        if (entry.deltaDegrees === 0) {
            setEntry(jointIndex, undefined);
            return;
        }
        const sending = { ...entry, status: 'sending' };
        setEntry(jointIndex, sending);
        let status = 'sent';
        try {
            await send(committedTargets());
        }
        catch {
            status = 'failed';
        }
        setEntry(jointIndex, { ...sending, status });
        resultTimers.set(jointIndex, setTimeout(() => {
            setEntry(jointIndex, undefined);
        }, timing.resultDisplayMs));
    };
    const add = (jointIndex, stepDegrees, range) => {
        clearTimeout(debounceTimers.get(jointIndex));
        const current = entries.get(jointIndex);
        if (current?.status === 'sending')
            return;
        clearTimeout(resultTimers.get(jointIndex));
        if (current?.status === 'queuing') {
            setEntry(jointIndex, {
                ...current,
                deltaDegrees: clampDelta(current, current.deltaDegrees + stepDegrees),
            });
            return;
        }
        setEntry(jointIndex, {
            jointIndex,
            ...range,
            deltaDegrees: clampDelta(range, stepDegrees),
            status: 'queuing',
        });
    };
    const scheduleSend = (jointIndex) => {
        clearTimeout(debounceTimers.get(jointIndex));
        if (entries.get(jointIndex)?.status !== 'queuing')
            return;
        debounceTimers.set(jointIndex, setTimeout(() => {
            void flush(jointIndex);
        }, timing.sendDebounceMs));
    };
    /**
     * One discrete press, such as a keyboard or assistive-technology activation.
     * `range` is the joint's current position and limits and is only read when the
     * press starts a new entry.
     */
    const tap = (jointIndex, stepDegrees, range) => {
        add(jointIndex, stepDegrees, range);
        scheduleSend(jointIndex);
    };
    /** A pointer press. Queues one step now and keeps adding while held. */
    const beginHold = (jointIndex, stepDegrees, range) => {
        clearHoldTimers();
        heldJointIndex = jointIndex;
        add(jointIndex, stepDegrees, range);
        holdDelayTimer = setTimeout(() => {
            holdRepeatTimer = setInterval(() => {
                add(jointIndex, stepDegrees, range);
            }, timing.holdRepeatIntervalMs);
        }, timing.holdRepeatDelayMs);
    };
    /** A pointer release. Stops repeating and schedules the held joint's send. */
    const endHold = () => {
        clearHoldTimers();
        if (heldJointIndex === undefined)
            return;
        scheduleSend(heldJointIndex);
        heldJointIndex = undefined;
    };
    const dispose = () => {
        clearHoldTimers();
        for (const timer of debounceTimers.values())
            clearTimeout(timer);
        for (const timer of resultTimers.values())
            clearTimeout(timer);
    };
    return {
        entryFor: (jointIndex) => entries.get(jointIndex),
        tap,
        beginHold,
        endHold,
        dispose,
    };
};
