<script>
	import { BROWSER } from 'esm-env'
	import { getContext, onDestroy, onMount, setContext, tick } from 'svelte'
	import { writable } from 'svelte/store'
	import ClsPad from '../internal/ClsPad.svelte'
	import InternalPaneInline from '../internal/InternalPaneInline.svelte'
	import { getElementIndex, isRootPane } from '../utils.js'
	export let disabled = false
	export let selectedIndex = 0
	export let theme = void 0
	const parentStore = getContext('parentStore')
	const tabGroupStore = writable()
	setContext('tabGroupStore', tabGroupStore)
	const tabIndexStore = writable()
	setContext('tabIndexStore', tabIndexStore)
	setContext('initialSelectedIndex', selectedIndex)
	const tabGroupInitialized = writable(false)
	const userCreatedPane = getContext('userCreatedPane')
	let indexElement
	onMount(async () => {
		$tabIndexStore = userCreatedPane === true ? getElementIndex(indexElement) : 0
		await tick()
		setSelectedIndex(selectedIndex)
		$tabGroupInitialized = true
	})
	onDestroy(() => {
		$tabGroupStore?.dispose()
	})
	function setUpListeners(t) {
		t?.on('select', (event) => {
			const isInDocument = indexElement?.isConnected ?? false
			if ($tabGroupInitialized && isInDocument && event.index >= 0) {
				selectedIndex = event.index
			}
		})
	}
	function setSelectedIndex(index) {
		const tabPageApi = $tabGroupStore?.pages.at(index)
		if (tabPageApi && !tabPageApi.selected) {
			tabPageApi.selected = true
		}
	}
	$: setUpListeners($tabGroupStore)
	$: $tabGroupStore !== void 0 && setSelectedIndex(selectedIndex)
	$: $tabGroupStore !== void 0 && ($tabGroupStore.disabled = disabled)
	$: theme &&
		$parentStore !== void 0 &&
		(userCreatedPane ?? !isRootPane($parentStore)) &&
		console.warn(
			'Set theme on the <Pane> component, not on its children! (Check nested <TabGroup> components for a theme prop.)',
		)
</script>

{#if parentStore}
	{#if BROWSER}
		<div bind:this={indexElement} style:display="none">
			<slot></slot>
		</div>
	{:else}
		<ClsPad keysAdd={['containerVerticalPadding', 'containerVerticalPadding']} {theme} />
		<div>
			<slot></slot>
		</div>
	{/if}
{:else}
	<InternalPaneInline {theme} userCreatedPane={false}>
		<svelte:self {disabled} bind:selectedIndex>
			<slot></slot>
		</svelte:self>
	</InternalPaneInline>
{/if}
