<script lang="ts">
	import type { HTMLAttributes } from 'svelte/elements'

	import { ToastVariant, useToast } from '@viamrobotics/prime-core'

	import type { FileDropperSuccess } from '#lib/fileDropper.js'

	import { createBufferGeometry } from '#lib/attribute.js'
	import { ColorFormat } from '#lib/buf/draw/v1/metadata_pb.js'
	import OverlayPortal from '#lib/components/overlay/Portals/OverlayPortal.svelte'
	import { traits } from '#lib/ecs/index.js'
	import { useWorld } from '#lib/ecs/useWorld.js'
	import { useCameraControls } from '#lib/hooks/useControls.svelte.js'
	import { useRelationships } from '#lib/hooks/useRelationships.svelte.js'
	import { spawnSnapshotEntities } from '#lib/snapshot.js'
	import { attachPointsBvh } from '#lib/three/pointsBvh.js'

	import { useFileDrop } from './useFileDrop.svelte'

	const props: HTMLAttributes<HTMLDivElement> = $props()

	const world = useWorld()
	const toast = useToast()
	const cameraControls = useCameraControls()
	const relationships = useRelationships()

	const fileDrop = useFileDrop(
		(result: FileDropperSuccess) => {
			switch (result.type) {
				case 'snapshot': {
					const spawned = spawnSnapshotEntities(world, result.snapshot)
					for (const entity of spawned) {
						relationships.apply(entity.entity, entity.relationships)
						const uuid = entity.entity.get(traits.UUID)
						if (uuid) relationships.flush(uuid)
					}

					const { sceneCamera } = result.snapshot.sceneMetadata ?? {}

					if (sceneCamera) {
						const { x = 0, y = 0, z = 0 } = sceneCamera.position ?? {}
						const { x: lx = 0, y: ly = 0, z: lz = 0 } = sceneCamera.lookAt ?? {}

						cameraControls.setPose({
							position: [x * 0.001, y * 0.001, z * 0.001],
							lookAt: [lx * 0.001, ly * 0.001, lz * 0.001],
						})
					}

					break
				}
				case 'pcd': {
					const geometry = createBufferGeometry(
						result.pcd.positions,
						{ colors: result.pcd.colors, colorFormat: ColorFormat.RGB },
						result.pcd.bounds
					)
					if (result.pcd.boundsTree) attachPointsBvh(geometry, result.pcd.boundsTree)

					world.spawn(
						traits.Name(result.name),
						traits.BufferGeometry(geometry),
						traits.Points,
						traits.DroppedFile,
						traits.Removable,
						traits.PointSampling({
							total: result.pcd.positions.length / 3,
							shuffled: result.pcd.shuffled,
						})
					)
					break
				}
				case 'ply': {
					world.spawn(
						traits.Name(result.name),
						traits.BufferGeometry(result.ply),
						traits.DroppedFile,
						traits.Removable
					)
					break
				}
			}

			toast({ message: `${result.name} loaded.`, variant: ToastVariant.Success })
		},
		(message) => toast({ message, variant: ToastVariant.Danger })
	)
</script>

<svelte:window
	ondragenter={fileDrop.ondragenter}
	ondragleave={fileDrop.ondragleave}
	ondragover={fileDrop.ondragover}
/>

<OverlayPortal>
	<div
		class={{
			'fixed inset-0 z-9999': true,
			'pointer-events-none': fileDrop.dropState === 'inactive',
			'bg-black/10': fileDrop.dropState !== 'inactive',
		}}
		role="region"
		aria-label="File drop zone"
		ondrop={fileDrop.ondrop}
		{...props}
	></div>
</OverlayPortal>
