// Annotation to mark external updates that shouldn't trigger onChange
export const externalUpdate = Annotation.define();
/** Create an editor StateField and updater function. */
const createSource = () => {
    const updateEffect = StateEffect.define();
    const source = StateField.define({
        create: () => undefined,
        update: (prevValue, transaction) => {
            let nextValue = prevValue;
            for (const effect of transaction.effects) {
                if (effect.is(updateEffect)) {
                    nextValue = effect.value;
                }
            }
            return nextValue;
        },
    });
    const update = (view, nextValue) => {
        view?.dispatch({ effects: [updateEffect.of(nextValue)] });
    };
    return [source, update];
};
const [readonly, setReadOnly] = createSource();
const [label, setLabel] = createSource();
const [errorMessageID, setErrorMessageID] = createSource();
const [isInvalid, setIsInvalid] = createSource();
const setDiffOriginal = (view, nextOriginal) => {
    if (nextOriginal !== undefined) {
        view?.dispatch({
            effects: updateOriginalDoc.of({
                doc: view.state.toText(nextOriginal),
                changes: ChangeSet.empty(0),
            }),
        });
    }
};
/**
 * Get the language extension for the specified language.
 */
const getLanguageExtension = (language = 'json') => {
    switch (language) {
        case 'json5': {
            return json5();
        }
        case 'python': {
            return new LanguageSupport(pythonLanguage);
        }
        case 'go': {
            return new LanguageSupport(goLanguage);
        }
        case 'sql': {
            return new LanguageSupport(StandardSQL.language);
        }
        default: {
            return json();
        }
    }
};
const stripUndefinedAttrs = (attrs) => {
    const result = {};
    for (const [key, value] of Object.entries(attrs)) {
        if (value !== undefined) {
            result[key] = value;
        }
    }
    return result;
};
/**
 * Create a CodeMirror extension list for a code editor.
 *
 * Adds various state fields and effects so that props changes
 * can be hooked to the editor without needing to completely
 * reconfigure or recreate the extensions list.
 *
 * @param options Initial values for editor state
 * @returns The extension list and hooks to reactively update the state
 */
export const createCodeExtensions = (options) => {
    const languageExtension = getLanguageExtension(options.language);
    const extensions = [
        readonly.init(() => options.readonly),
        label.init(() => options.label),
        errorMessageID.init(() => options.errorMessageID),
        isInvalid.init(() => options.isInvalid),
        basicSetup,
        languageExtension,
        tooltipTheme,
        EditorView.contentAttributes.compute([label, errorMessageID, isInvalid], (state) => stripUndefinedAttrs({
            'aria-label': state.field(label),
            'aria-invalid': state.field(isInvalid) === true ? 'true' : undefined,
            'aria-errormessage': state.field(errorMessageID),
        })),
        EditorView.editable.from(readonly, (readonlyValue) => !readonlyValue),
        EditorState.readOnly.from(readonly),
        EditorView.domEventObservers({
            blur: options.onBlur,
            focus: options.onFocus,
        }),
    ];
    // Only enable tab-as-spaces for Python and Go
    if (options.language === 'python' || options.language === 'go') {
        extensions.push(keymap.of([indentWithTab]));
    }
    if (options.diffOriginal !== undefined) {
        extensions.push(unifiedMergeView({
            original: options.diffOriginal,
            mergeControls: false,
        }));
    }
    if (options.lineWrapping) {
        extensions.push(EditorView.lineWrapping);
    }
    // Add custom extensions (like LSP)
    if (options.extraExtensions) {
        extensions.push(...options.extraExtensions);
    }
    return extensions;
};
/**
 * Dispatch change events when the contents of the editor change.
 *
 * Create a new dispatch function whenever the editor is re-created
 */
export const createDispatchTransactions = (onChange, language = 'json') => {
    let currentValue;
    return (transactions, view) => {
        view.update(transactions);
        let nextValue = view.state.doc.toString();
        // Only apply default empty object for JSON/JSON5
        if (nextValue === '' && (language === 'json' || language === 'json5')) {
            nextValue = '{}';
        }
        currentValue ??= nextValue;
        // Check if this is an external update (e.g., syncing with initialValue)
        const isExternalUpdate = transactions.some((tr) => tr.annotation(externalUpdate));
        if (nextValue !== currentValue && !isExternalUpdate) {
            currentValue = nextValue;
            onChange(currentValue);
        }
        else if (isExternalUpdate) {
            // Update currentValue for external updates without triggering onChange
            currentValue = nextValue;
        }
    };
};
export { setDiffOriginal, setErrorMessageID, setIsInvalid, setLabel, setReadOnly, };
